/* Cycle46 bounded compositional MIR acceptance corpus. */
#include "mir.h"
#include "mir-gen.h"
#include "mir-debug.h"
#include <inttypes.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static MIR_context_t c;
static void ap(MIR_item_t f,MIR_insn_t i){MIR_append_insn(c,f,i);}
#define R(x) MIR_new_reg_op(c,(x))
#define I(x) MIR_new_int_op(c,(int64_t)(x))
#define D(x) MIR_new_double_op(c,(double)(x))
#define L(x) MIR_new_label_op(c,(x))
static MIR_reg_t loc(MIR_item_t f,MIR_type_t t,const char*n){return MIR_new_func_reg(c,f->u.func,t,n);}
static MIR_reg_t arg(MIR_item_t f,const char*n){return MIR_reg(c,n,f->u.func);}
static MIR_item_t find(const char*n){MIR_module_t m;MIR_item_t i;for(m=DLIST_HEAD(MIR_module_t,*MIR_get_module_list(c));m;m=DLIST_NEXT(MIR_module_t,m))for(i=DLIST_HEAD(MIR_item_t,m->items);i;i=DLIST_NEXT(MIR_item_t,i))if(i->item_type==MIR_func_item&&!strcmp(MIR_item_name(c,i),n))return i;return NULL;}
static void finish(MIR_item_t f,const char*n){ap(f,MIR_new_ret_insn(c,1,R(MIR_reg(c,n,f->u.func))));MIR_finish_func(c);MIR_new_export(c,MIR_item_name(c,f));}
static MIR_item_t make_conv_branch(int k){char name[32];MIR_type_t rt=MIR_T_I64;snprintf(name,sizeof name,"cvbr_%d",k);MIR_item_t f=MIR_new_func(c,name,1,&rt,1,MIR_T_I64,"x");MIR_reg_t x=arg(f,"x"),v=loc(f,MIR_T_I64,"v"),r=loc(f,MIR_T_I64,"r");MIR_label_t yes=MIR_new_label(c),done=MIR_new_label(c);MIR_insn_code_t cv=(k&1)?MIR_UEXT8:MIR_EXT8;int64_t th=(int64_t[]){-1,0,1,127}[k];ap(f,MIR_new_insn(c,cv,R(v),R(x)));ap(f,MIR_new_insn(c,MIR_BGE,L(yes),R(v),I(th)));ap(f,MIR_new_insn(c,MIR_MOV,R(r),I(20+k)));ap(f,MIR_new_insn(c,MIR_JMP,L(done)));ap(f,yes);ap(f,MIR_new_insn(c,MIR_MOV,R(r),I(10+k)));ap(f,done);finish(f,"r");return f;}
static const MIR_insn_code_t ovcode[]={MIR_ADDO,MIR_SUBO,MIR_MULO,MIR_UMULO};
static MIR_item_t make_ov_branch(int k){char name[32];MIR_type_t rt=MIR_T_I64;snprintf(name,sizeof name,"ovbr_%d",k);MIR_item_t f=MIR_new_func(c,name,1,&rt,2,MIR_T_I64,"a",MIR_T_I64,"b");MIR_reg_t a=arg(f,"a"),b=arg(f,"b"),v=loc(f,MIR_T_I64,"v"),r=loc(f,MIR_T_I64,"r");MIR_label_t ov=MIR_new_label(c),done=MIR_new_label(c);ap(f,MIR_new_insn(c,ovcode[k],R(v),R(a),R(b)));ap(f,MIR_new_insn(c,(k==3?MIR_UBO:MIR_BO),L(ov)));ap(f,MIR_new_insn(c,MIR_MOV,R(r),I(200+k)));ap(f,MIR_new_insn(c,MIR_JMP,L(done)));ap(f,ov);ap(f,MIR_new_insn(c,MIR_MOV,R(r),I(100+k)));ap(f,done);finish(f,"r");return f;}
static MIR_item_t make_memcv(int k){char name[32];MIR_type_t rt=MIR_T_I64;snprintf(name,sizeof name,"memcv_%d",k);MIR_item_t f=MIR_new_func(c,name,1,&rt,1,MIR_T_P,"p");MIR_reg_t p=arg(f,"p"),v=loc(f,MIR_T_I64,"v"),t=loc(f,MIR_T_I64,"t"),r=loc(f,MIR_T_I64,"r");MIR_type_t mt=(k&1)?MIR_T_U8:MIR_T_I8;MIR_insn_code_t cv=(k&1)?MIR_UEXT8:MIR_EXT8;ap(f,MIR_new_insn(c,MIR_MOV,R(v),MIR_new_mem_op(c,mt,0,p,0,0)));ap(f,MIR_new_insn(c,cv,R(t),R(v)));ap(f,MIR_new_insn(c,MIR_ADD,R(r),R(t),I(k+1)));ap(f,MIR_new_insn(c,MIR_MOV,MIR_new_mem_op(c,MIR_T_I64,8,p,0,0),R(r)));finish(f,"r");return f;}
static MIR_item_t make_loopmem(int k){char name[32];MIR_type_t rt=MIR_T_I64;snprintf(name,sizeof name,"loopmem_%d",k);MIR_item_t f=MIR_new_func(c,name,1,&rt,2,MIR_T_P,"p",MIR_T_I64,"n");MIR_reg_t p=arg(f,"p"),n=arg(f,"n"),i=loc(f,MIR_T_I64,"i"),v=loc(f,MIR_T_I64,"v"),s=loc(f,MIR_T_I64,"s");MIR_label_t loop=MIR_new_label(c),done=MIR_new_label(c);ap(f,MIR_new_insn(c,MIR_MOV,R(i),I(0)));ap(f,MIR_new_insn(c,MIR_MOV,R(s),I(0)));ap(f,loop);ap(f,MIR_new_insn(c,MIR_BGE,L(done),R(i),R(n)));ap(f,MIR_new_insn(c,MIR_MOV,R(v),MIR_new_mem_op(c,(k&1)?MIR_T_U8:MIR_T_I8,0,p,i,1)));ap(f,MIR_new_insn(c,(k&1)?MIR_UEXT8:MIR_EXT8,R(v),R(v)));ap(f,MIR_new_insn(c,MIR_ADD,R(s),R(s),R(v)));ap(f,MIR_new_insn(c,MIR_ADD,R(i),R(i),I(1)));ap(f,MIR_new_insn(c,MIR_JMP,L(loop)));ap(f,done);finish(f,"s");return f;}
static MIR_item_t mkproto(const char*n,MIR_type_t ret,size_t na,MIR_var_t*args){return MIR_new_proto_arr(c,n,1,&ret,na,args);}
static MIR_insn_t call1(MIR_item_t p,MIR_item_t callee,MIR_op_t out,MIR_op_t in){MIR_op_t ops[]={MIR_new_ref_op(c,p),MIR_new_ref_op(c,callee),out,in};return MIR_new_insn_arr(c,MIR_CALL,4,ops);}
static MIR_insn_t call2(MIR_item_t p,MIR_item_t callee,MIR_op_t out,MIR_op_t a,MIR_op_t b){MIR_op_t ops[]={MIR_new_ref_op(c,p),MIR_new_ref_op(c,callee),out,a,b};return MIR_new_insn_arr(c,MIR_CALL,5,ops);}
static MIR_item_t make_callcv_callee(int k){char name[32];MIR_type_t rt=MIR_T_I64;snprintf(name,sizeof name,"callee_%d",k);MIR_item_t f=MIR_new_func(c,name,1,&rt,1,MIR_T_I64,"x");MIR_reg_t x=arg(f,"x"),r=loc(f,MIR_T_I64,"r");ap(f,MIR_new_insn(c,MIR_MUL,R(r),R(x),I(2+k)));ap(f,MIR_new_insn(c,MIR_ADD,R(r),R(r),I(7+k)));finish(f,"r");return f;}
static MIR_item_t make_callcv(int k,MIR_item_t callee,MIR_item_t proto){char name[32];MIR_type_t rt=MIR_T_I64;snprintf(name,sizeof name,"callcv_%d",k);MIR_item_t f=MIR_new_func(c,name,1,&rt,2,MIR_T_I64,"x",MIR_T_D,"d");MIR_reg_t x=arg(f,"x"),d=arg(f,"d"),di=loc(f,MIR_T_I64,"di"),in=loc(f,MIR_T_I64,"in"),r=loc(f,MIR_T_I64,"r");ap(f,MIR_new_insn(c,MIR_D2I,R(di),R(d)));ap(f,MIR_new_insn(c,MIR_ADD,R(in),R(x),R(di)));ap(f,call1(proto,callee,R(r),R(in)));ap(f,MIR_new_insn(c,MIR_ADD,R(r),R(r),R(x)));finish(f,"r");return f;}
static MIR_item_t make_flagmix(int k){char name[32];MIR_type_t rt=MIR_T_I64;snprintf(name,sizeof name,"flagmix_%d",k);MIR_item_t f=MIR_new_func(c,name,1,&rt,2,MIR_T_I64,"flag",MIR_T_I64,"value");MIR_reg_t fl=arg(f,"flag"),v=arg(f,"value"),mask=loc(f,MIR_T_I64,"mask"),m=loc(f,MIR_T_I64,"m"),r=loc(f,MIR_T_I64,"r");ap(f,MIR_new_insn(c,MIR_AND,R(mask),R(v),I(255)));ap(f,MIR_new_insn(c,MIR_MUL,R(m),R(fl),I(100)));ap(f,MIR_new_insn(c,MIR_ADD,R(r),R(m),R(mask)));ap(f,MIR_new_insn(c,MIR_ADD,R(r),R(r),I(k)));finish(f,"r");return f;}
static MIR_item_t make_ovcall(int k,MIR_item_t callee,MIR_item_t proto){char name[32];MIR_type_t rt=MIR_T_I64;snprintf(name,sizeof name,"ovcall_%d",k);MIR_item_t f=MIR_new_func(c,name,1,&rt,2,MIR_T_I64,"a",MIR_T_I64,"b");MIR_reg_t a=arg(f,"a"),b=arg(f,"b"),v=loc(f,MIR_T_I64,"v"),flag=loc(f,MIR_T_I64,"flag"),r=loc(f,MIR_T_I64,"r");MIR_label_t ov=MIR_new_label(c),join=MIR_new_label(c);ap(f,MIR_new_insn(c,MIR_ADDO,R(v),R(a),R(b)));ap(f,MIR_new_insn(c,MIR_BO,L(ov)));ap(f,MIR_new_insn(c,MIR_MOV,R(flag),I(0)));ap(f,MIR_new_insn(c,MIR_JMP,L(join)));ap(f,ov);ap(f,MIR_new_insn(c,MIR_MOV,R(flag),I(1)));ap(f,join);ap(f,call2(proto,callee,R(r),R(flag),R(v)));finish(f,"r");return f;}
static void build(void){MIR_var_t iarg[]={{MIR_T_I64,"x",0}},flagargs[]={{MIR_T_I64,"flag",0},{MIR_T_I64,"value",0}};MIR_item_t p1,pc;int k;c=MIR_init();MIR_new_module(c,"cycle46_composites");
 for(k=0;k<4;k++){make_conv_branch(k);make_ov_branch(k);make_memcv(k);make_loopmem(k);}
 p1=mkproto("callee_proto",MIR_T_I64,1,iarg);pc=mkproto("flagmix_proto",MIR_T_I64,2,flagargs);
 for(k=0;k<4;k++){MIR_item_t cal=make_callcv_callee(k);make_callcv(k,cal,p1);MIR_item_t mix=make_flagmix(k);make_ovcall(k,mix,pc);}
 MIR_finish_module(c);
}
static int64_t sign8(uint8_t x){return (x&128)?(int64_t)x-256:x;}
static int64_t oracle_ov(int k,int64_t a,int64_t b){if(k==0)return ((__int128)a+(__int128)b)>INT64_MAX||((__int128)a+(__int128)b)<INT64_MIN;if(k==1)return ((__int128)a-(__int128)b)>INT64_MAX||((__int128)a-(__int128)b)<INT64_MIN;if(k==2)return ((__int128)a*(__int128)b)>INT64_MAX||((__int128)a*(__int128)b)<INT64_MIN;return (__uint128_t)(uint64_t)a*(__uint128_t)(uint64_t)b>UINT64_MAX;}
static int exec(int opt,int emit){MIR_module_t m;MIR_item_t f;int k,fail=0;size_t count=0;static const int64_t xs[]={-129,-128,-1,0,1,127,128,255,256,511};static const int64_t pairs[][2]={{0,0},{1,2},{INT64_MAX,1},{INT64_MIN,1},{INT64_MAX,2},{UINT64_MAX,2}};for(m=DLIST_HEAD(MIR_module_t,*MIR_get_module_list(c));m;m=DLIST_NEXT(MIR_module_t,m))MIR_load_module(c,m);MIR_gen_init(c);MIR_gen_set_optimize_level(c,(unsigned)opt);MIR_link(c,MIR_set_gen_interface,NULL);
 for(k=0;k<4;k++){char name[32];snprintf(name,sizeof name,"cvbr_%d",k);f=find(name);for(size_t j=0;j<10;j++){int64_t x=xs[j],q=(k&1)?(int64_t)((uint64_t)x&255):sign8((uint8_t)x),th=(int64_t[]){-1,0,1,127}[k],want=q>=th?10+k:20+k;MIR_val_t a[1],r[1];a[0].i=x;MIR_interp_arr(c,f,r,1,a);typedef int64_t(*fn)(int64_t);int64_t got=((fn)MIR_gen(c,f))(x);if(r[0].i!=want||got!=want){fprintf(stderr,"cvbr mismatch k=%d x=%" PRId64 " want=%" PRId64 " interp=%" PRId64 " jit=%" PRId64 "\n",k,x,want,r[0].i,got);fail++;}if(emit)printf("{\"family\":\"conversion_branch\",\"case\":\"%s\",\"input\":\"%" PRId64 "\",\"expected\":%" PRId64 ",\"interp\":%" PRId64 ",\"jit\":%" PRId64 "}\n",name,x,want,r[0].i,got);count++;}}
 for(k=0;k<4;k++){char name[32];snprintf(name,sizeof name,"ovbr_%d",k);f=find(name);for(size_t j=0;j<6;j++){int64_t a0=pairs[j][0],b0=pairs[j][1];int want=oracle_ov(k,a0,b0)?100+k:200+k;MIR_val_t a[2],r[1];a[0].i=a0;a[1].i=b0;MIR_interp_arr(c,f,r,2,a);typedef int64_t(*fn)(int64_t,int64_t);int64_t got=((fn)MIR_gen(c,f))(a0,b0);if(r[0].i!=want||got!=want){fprintf(stderr,"ovbr mismatch %d/%zu\n",k,j);fail++;}if(emit)printf("{\"family\":\"overflow_branch\",\"case\":\"%s\",\"expected\":%d,\"interp\":%" PRId64 ",\"jit\":%" PRId64 "}\n",name,want,r[0].i,got);count++;}}
 for(k=0;k<4;k++){char name[32];snprintf(name,sizeof name,"memcv_%d",k);f=find(name);for(int j=0;j<4;j++){uint8_t buf[24];memset(buf,0xa5,sizeof buf);buf[0]=(uint8_t[]){0x80,0x7f,0xff,0x01}[j];int64_t base=(k&1)?buf[0]:sign8(buf[0]),want=base+k+1,got;MIR_val_t a[1],r[1];a[0].a=buf;MIR_interp_arr(c,f,r,1,a);got=r[0].i;typedef int64_t(*fn)(void*);int64_t jit=((fn)MIR_gen(c,f))(buf),stored;memcpy(&stored,buf+8,8);if(got!=want||jit!=want||stored!=want){fprintf(stderr,"memcv mismatch k=%d j=%d\n",k,j);fail++;}for(int b=1;b<8;b++)if(buf[b]!=0xa5)fail++;for(int b=16;b<24;b++)if(buf[b]!=0xa5)fail++;if(emit)printf("{\"family\":\"memory_conversion\",\"case\":\"%s\",\"expected\":%" PRId64 ",\"interp\":%" PRId64 ",\"jit\":%" PRId64 ",\"stored\":%" PRId64 "}\n",name,want,got,jit,stored);count++;}}
 for(k=0;k<4;k++){char name[32];snprintf(name,sizeof name,"loopmem_%d",k);f=find(name);for(int n=0;n<=3;n++){uint8_t b[16];for(int i=0;i<16;i++)b[i]=(uint8_t)(0x7e + i*19 + n);int64_t want=0;for(int i=0;i<n;i++)want+=(k&1)?b[i]:sign8(b[i]);MIR_val_t a[2],r[1];a[0].a=b;a[1].i=n;MIR_interp_arr(c,f,r,2,a);typedef int64_t(*fn)(void*,int64_t);int64_t got=((fn)MIR_gen(c,f))(b,n);if(r[0].i!=want||got!=want)fail++;if(emit)printf("{\"family\":\"loop_memory\",\"case\":\"%s\",\"n\":%d,\"expected\":%" PRId64 ",\"interp\":%" PRId64 ",\"jit\":%" PRId64 "}\n",name,n,want,r[0].i,got);count++;}}
 for(k=0;k<4;k++){char name[32];snprintf(name,sizeof name,"callcv_%d",k);f=find(name);for(int j=0;j<10;j++){int64_t x=(int64_t[]){-20,-1,0,18,100,7,33,-41,512,-512}[j];double d=(double[]){-3.75,-0.9,0.0,4.8,11.2,1.25,-7.5,2.0,99.9,-99.9}[j];int64_t di=(int64_t)trunc(d),in=x+di,want=in*(2+k)+7+k+x;MIR_val_t a[2],r[1];a[0].i=x;a[1].d=d;MIR_interp_arr(c,f,r,2,a);typedef int64_t(*fn)(int64_t,double);int64_t got=((fn)MIR_gen(c,f))(x,d);if(r[0].i!=want||got!=want)fail++;if(emit)printf("{\"family\":\"call_conversion\",\"case\":\"%s\",\"expected\":%" PRId64 ",\"interp\":%" PRId64 ",\"jit\":%" PRId64 "}\n",name,want,r[0].i,got);count++;}}
 for(k=0;k<4;k++){char name[32];snprintf(name,sizeof name,"ovcall_%d",k);f=find(name);for(size_t j=0;j<6;j++){int64_t a0=pairs[j][0],b0=pairs[j][1],v=(int64_t)((uint64_t)a0+(uint64_t)b0),fl=oracle_ov(0,a0,b0),want=fl*100+(v&255)+k;MIR_val_t a[2],r[1];a[0].i=a0;a[1].i=b0;MIR_interp_arr(c,f,r,2,a);typedef int64_t(*fn)(int64_t,int64_t);int64_t got=((fn)MIR_gen(c,f))(a0,b0);if(r[0].i!=want||got!=want)fail++;if(emit)printf("{\"family\":\"overflow_call\",\"case\":\"%s\",\"expected\":%" PRId64 ",\"interp\":%" PRId64 ",\"jit\":%" PRId64 "}\n",name,want,r[0].i,got);count++;}}
 MIR_gen_finish(c);fprintf(stderr,"Cycle46 composite observations=%zu failures=%d optimize=%d\n",count,fail,opt);return fail?1:0;}
static int readprog(int bin,const char*path){FILE*f=fopen(path,"rb");long n;char*s;if(!f)return 2;c=MIR_init();if(bin)MIR_read(c,f);else{fseek(f,0,SEEK_END);n=ftell(f);fseek(f,0,SEEK_SET);s=malloc((size_t)n+1);fread(s,1,(size_t)n,f);s[n]=0;MIR_scan_string(c,s);free(s);}fclose(f);return 0;}
static int emit_native(int shared,const char*path,int opt){MIR_module_t m;MIR_item_t i;void*buf=NULL;size_t n=0;int rc;struct MIR_object_exec_params par={0};const char*needed[]={"libc.so.6"};for(m=DLIST_HEAD(MIR_module_t,*MIR_get_module_list(c));m;m=DLIST_NEXT(MIR_module_t,m))MIR_load_module(c,m);MIR_gen_init(c);MIR_gen_set_optimize_level(c,(unsigned)opt);MIR_gen_set_object_mode(c,1);MIR_link(c,MIR_set_gen_interface,NULL);for(m=DLIST_HEAD(MIR_module_t,*MIR_get_module_list(c));m;m=DLIST_NEXT(MIR_module_t,m))for(i=DLIST_HEAD(MIR_item_t,m->items);i;i=DLIST_NEXT(MIR_item_t,i))if(i->item_type==MIR_func_item)(void)MIR_gen(c,i);if(shared){par.shared_p=1;par.needed=needed;par.n_needed=1;rc=MIR_gen_object_emit_executable(c,&par,&buf,&n);}else rc=MIR_gen_object_emit(c,&buf,&n);if(rc||!buf)return 60;FILE*f=fopen(path,"wb");if(!f)return 61;if(fwrite(buf,1,n,f)!=n||fclose(f))return 62;free(buf);MIR_gen_finish(c);return 0;}
int main(int argc,char**argv){int opt=2,rc=0;if(argc>=3&&(!strcmp(argv[1],"--text")||!strcmp(argv[1],"--binary"))){rc=readprog(!strcmp(argv[1],"--binary"),argv[2]);if(rc)return rc;if(argc>=5&&!strcmp(argv[3],"--opt"))opt=atoi(argv[4]);}else{build();{FILE*f=fopen("results/cycle46-mir-integration-gate/composite.mir","w");if(f){MIR_output(c,f);fclose(f);}f=fopen("results/cycle46-mir-integration-gate/composite.bmir","wb");if(f){MIR_write(c,f);fclose(f);}}if(argc>=4&&(!strcmp(argv[1],"--object")||!strcmp(argv[1],"--shared"))){if(argc>=4)opt=atoi(argv[3]);rc=emit_native(!strcmp(argv[1],"--shared"),argv[2],opt);MIR_finish(c);return rc;}if(argc>=3&&!strcmp(argv[1],"--opt"))opt=atoi(argv[2]);}rc=exec(opt,1);MIR_finish(c);return rc;}
